"""Mini App browser flows with explicitly synthetic HTTP fixtures; not hosted proof."""
import unittest,threading,http.server,functools,os,shutil,json,base64
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
class Quiet(http.server.SimpleHTTPRequestHandler):
 def log_message(self,*args):pass
class BrowserTests(unittest.TestCase):
 @classmethod
 def setUpClass(cls):
  cls.server=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Quiet,directory=str(ROOT/'miniapp')));cls.thread=threading.Thread(target=cls.server.serve_forever,daemon=True);cls.thread.start();cls.origin='http://127.0.0.1:'+str(cls.server.server_port);cls.p=sync_playwright().start();cls.browser=cls.p.webkit.launch() if os.environ.get('WASEET_BROWSER')=='webkit' else cls.p.chromium.launch(executable_path=shutil.which('chromium'),args=['--no-sandbox'])
 @classmethod
 def tearDownClass(cls):cls.browser.close();cls.p.stop();cls.server.shutdown();cls.server.server_close();cls.thread.join()
 def setUp(self):
  self.context=self.browser.new_context(viewport={'width':390,'height':844});self.page=self.context.new_page();self.page.set_default_timeout(6000);self.errors=[];self.calls=[];self.role='market';self.logged=True;self.ads=[];self.orders=[];self.rep_rows=[];self.admin_users=[];self.admin_ads=[];self.channel_outcome='sent';self.fail_user_save=False;self.peer_name='أحمد البائع';self.peer_avatar=None;self.inbox_unread=0;self.image=0;self.private_media=False;self.authorized_media=0;self.official=False;self.packages=[{'id':'package-'+str(d),'name':'ترويج '+str(d)+' يوم','description':'وصف الباقة','days':d,'stars':None,'enabled':False,'priority':100,'version':1} for d in [1,7,14,30]];self.notify_prefs={'enabled':False,'scope':'all','governorate':None,'categories':[],'operational':True,'rep_goods':True};self.settings={'channel':None,'channel_verified':False,'auto_publish':False,'purchases_enabled':False,'payments_verified':False,'publications':[]}
  self.page.on('pageerror',lambda e:self.errors.append(str(e)));self.page.route('**/*',self.route)
 def tearDown(self):self.context.close();self.assertEqual(self.errors,[])
 def fixture(self):return {'id':'00000000-0000-0000-0000-000000000099','owner_id':'member-one','title':'إعلان اختباري','category':'أثاث','area':'بغداد','price':5000,'condition':'used','negotiable':True,'description':'وصف اختباري','images':[],'status':'active'}
 def route(self,r):
  url=r.request.url
  if url=='https://telegram.org/js/telegram-web-app.js':
   r.fulfill(content_type='application/javascript',body="window.Telegram={WebApp:{initData:'synthetic-test-data',initDataUnsafe:{user:{id:1,role:'admin'}},ready(){},expand(){},openTelegramLink(url){window.sharedLink=url},onEvent(name,fn){if(name==='themeChanged')window.testTheme=fn},openInvoice(url,cb){window.invoiceOpened=url;cb('paid')}}};");return
  if '/api/' in url:
   payload=json.loads(r.request.post_data or '{}') if r.request.method=='POST' and '/api/images' not in url else {};self.calls.append({'path':url.split('/api/')[1],'body':payload});data={}
   if '/api/listings/' in url:data={'data':self.ads[0]}
   elif '/api/profile/' in url:data={'data':{'name':'مدير وسيط','subtitle':'الإدارة الرسمية لمنصة وسيط','verified_internal':True,'verification_source':'waseet_internal'}}
   elif '/api/listings' in url:data={'data':self.ads,'promotionStars':50}
   elif '/api/notifications' in url:
    op=payload.get('operation')
    if op=='reject_listing':
     ad=next(a for a in self.admin_ads if a['id']==payload['data']['id']);ad.update(status='hidden',approved_at=None,review_state='rejected');r.fulfill(json={'data':{'saved':True,'listing':ad}});return
    if op=='presence' and payload.get('data',{}).get('read_id'):self.inbox_unread=0
    if op=='save':self.notify_prefs.update(payload.get('data',{}))
    if op=='unsubscribe':self.notify_prefs['enabled']=False
    data={'data':self.notify_prefs if op in ['get','save'] else {}}
   elif '/api/channel/settings' in url:self.settings.update(channel=payload.get('channel'),auto_publish=payload.get('auto',False),channel_verified=True);data={'ok':True,'title':'قناة اختبار معزولة','channel':self.settings['channel']}
   elif '/api/images' in url:self.image+=1;data={'id':'00000000-0000-0000-0000-'+str(self.image).zfill(12)}
   elif '/api/invoice' in url:data={'invoice':'https://t.me/$synthetic','order':'order-one'}
   else:
    action=payload.get('action');result={}
    if action=='me':
     if not self.logged:r.fulfill(status=401,json={'error':'telegram_session_required'});return
     result={'id':'member-one','name':'مدير وسيط' if self.official else 'مستخدم اختبار','role':self.role,'verified_internal':self.official,'verification_source':'waseet_internal' if self.official else ''}
    elif action=='settings':result={**self.settings,'packages':self.packages}
    elif action=='packages_save':
     result=payload['data'];self.packages=[({**p,**result,'version':p['version']+1} if p['id']==result.get('id') else p) for p in self.packages]
    elif action=='rep_application':result={'application':None,'training':{}}
    elif action=='lesson':result={'lessons':[1,2,3,4,5]}
    elif action=='quiz':result={'passed':True,'score':5}
    elif action=='rep_apply':result={'id':'application-one','status':'pending'}
    elif action=='rep_requests':result=self.rep_rows
    elif action=='rep_review':
     for row in self.rep_rows:
      if row['id']==payload['data']['id']:row.update(status=payload['data']['status'])
     result={}
    elif action=='save':
     p=payload['data'];aid=p.get('id') or '00000000-0000-0000-0000-000000000100';ad={**self.fixture(),**p,'id':aid,'owner_id':'member-one','status':'active','author':{'name':'بائع الاختبار','avatar':None}};self.ads=[ad]+[a for a in self.ads if a['id']!=aid];result={'id':aid}
    elif action in ['mine','favorites']:result=self.ads
    elif action in ['orders']:result=self.orders
    elif action in ['thread','conversation']:result={'id':'thread-one','title':'محادثة اختبار','peer':{'name':self.peer_name,'verified_internal':False,'avatar':self.peer_avatar},'peer_role':'seller'}
    elif action=='inbox':result=[{'id':'thread-one','title':'محادثة اختبار','unread_count':self.inbox_unread,'unread_more':False,'peer':{'name':self.peer_name,'verified_internal':False,'avatar':self.peer_avatar}}]
    elif action=='messages':result=[{'id':'00000000-0000-0000-0000-000000000080','sender_id':'another','body':'<img src=x onerror=window.injected=1>'}]
    elif action=='rep':result={'sales':[],'commission_iqd':0}
    elif action=='publication_preview':result={'listing_id':'ad-review','title':'معاينة كاملة','photo_count':3,'album':True,'caption':'اسم الغرض والسعر','details':['المحافظة: بغداد\nالقسم: أثاث\nالحالة: مستعمل\nالوصف الكامل مع ضرر معلن\nقابل للتفاوض'],'requires_approval':True,'sent':False}
    elif action=='admin':
     f=payload.get('data',{}).get('listing_filter','all');result={'stats':{'users':150,'listings':90,'stars_received':500},'users':self.admin_users,'listings':[a for a in self.admin_ads if f=='all' or a['review_state']==f],'listing_filter':f,'listings_has_more':False,'reports':[],'orders':[],'support':[]}
    elif action=='admin_user':
     if self.fail_user_save:r.fulfill(status=403,json={'error':'action_denied'});return
     p=payload['data'];u=next(u for u in self.admin_users if u['id']==p['id']);u.update({('role' if p['operation']=='role' else 'banned'):p['role' if p['operation']=='role' else 'banned']});result={'saved':True,'user':u}
    elif action=='admin_user_state':result=next(u for u in self.admin_users if u['id']==payload['data']['id'])
    elif action in ['admin_listing_approve','admin_listing','admin_listing_state']:
     ad=next(a for a in self.admin_ads if a['id']==payload['data']['id'])
     if action=='admin_listing_approve':ad.update(approved_at='2026-10-27T00:00:00Z',review_state='published',channel={'state':self.channel_outcome})
     if action=='admin_listing':
      state=payload['data']['status'];ad.update(status=state,approved_at=None,review_state='pending' if state=='active' else 'rejected')
     result=ad if action=='admin_listing_state' else {'saved':True,'approved':ad['review_state']=='published','listing':ad,'publication':ad['channel']}

    data={'data':result}
   r.fulfill(json=data);return
  if '/media/' in url and self.private_media and not r.request.headers.get('x-telegram-init-data'):r.fulfill(status=404,body='Not found');return
  if '/media/' in url and r.request.headers.get('x-telegram-init-data'):self.authorized_media+=1
  if '/media/' in url:r.fulfill(content_type='image/png',body=(ROOT.parent/'assets/waseet-192.png').read_bytes());return
  # WebKit routes local object URLs; Chromium resolves them without interception.
  if url.startswith('blob:'+self.origin+'/'):r.continue_();return
  if url.startswith(self.origin):r.continue_()
  else:r.abort()
 def open(self):self.page.goto(self.origin,wait_until='networkidle')
